import { FORM_UID, projectForm } from "../form-projection";

import { PLAN_UID, projectPlans } from "../plan-projection";

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

function startRead(ctx: ReadContext) {
  ctx.set("Cache-Control", "no-store");
  return (status: number, code: string) => {
    ctx.body = { error: { code } };
    ctx.status = status;
  };
}

export default {
  async readForm(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: "published",
        filters: { country },
        populate: { fields: { populate: ["options", "rules"] } },
        limit: 2,
      });
    } catch {
      strapi.log.error("Quote form document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    if (!documents.length) return fail(404, "FORM_NOT_PUBLISHED");
    const form =
      documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn("A published quote form configuration was rejected.");
      return fail(503, "FORM_UNAVAILABLE");
    }
    ctx.body = form;
    ctx.status = 200;
  },
  async readPlans(ctx: ReadContext) {
    const fail = startRead(ctx);
    const country = ctx.params["country"];
    if (!isCountry(country)) return fail(404, "UNSUPPORTED_COUNTRY");
    if (ctx.querystring) return fail(400, "INVALID_REQUEST");

    let documents;
    try {
      documents = await strapi.documents(PLAN_UID).findMany({
        status: "published",
        filters: { country, active: true },
        populate: ["coverages", "benefits"],
        limit: MAX_PLANS + 1,
      });
    } catch {
      strapi.log.error("Quote plan document retrieval failed.");
      return fail(503, "CONTENT_UNAVAILABLE");
    }

    const catalog = projectPlans(documents, country);
    if (!catalog) {
      strapi.log.warn("A published quote plan catalog was rejected.");
      return fail(503, "PLANS_UNAVAILABLE");
    }
    ctx.body = catalog;
    ctx.status = 200;
  },
};
export const READ_FORM_ACTION = "api::quote-content.quote-content.readForm";

export const READ_PLANS_ACTION = "api::quote-content.quote-content.readPlans";

export default {
  routes: [
    {
      method: "GET",
      path: "/quote-content/v1/:country/form",
      handler: READ_FORM_ACTION,
      config: { auth: { scope: [READ_FORM_ACTION] } },
    },
    {
      method: "GET",
      path: "/quote-content/v1/:country/plans",
      handler: READ_PLANS_ACTION,
      config: { auth: { scope: [READ_PLANS_ACTION] } },
    },
  ],
};
import type { Core } from "@strapi/strapi";
import { FORM_UID } from "./api/quote-content/form-projection";
import { PLAN_UID } from "./api/quote-content/plan-projection";
import {
  READ_FORM_ACTION,
  READ_PLANS_ACTION,
} from "./api/quote-content/routes/quote-content";
import { seedForm } from "./seed-forms";
import { PLAN_EXPANSION_KEY, planCountries, seedPlans } from "./seed-plans";

async function restrictPublicRole(strapi: Core.Strapi) {
  await strapi.db.transaction(async () => {
    const roles = strapi.db.query("plugin::users-permissions.role");
    const publicRole = await roles.findOne({ where: { type: "public" } });
    if (!publicRole)
      throw new Error(
        "The Public role is unavailable during quote initialization.",
      );

    const permissions = strapi.db.query("plugin::users-permissions.permission");
    const grants = await permissions.findMany({
      select: ["id", "action"],
      where: { role: publicRole.id },
    });
    const expectedActions = [READ_FORM_ACTION, READ_PLANS_ACTION];
    const retained = expectedActions.map((action) =>
      grants.find((grant) => grant.action === action),
    );
    const obsolete = grants
      .filter((grant) => !retained.includes(grant))
      .map(({ id }) => id);
    if (obsolete.length) {
      await permissions.deleteMany({ where: { id: { $in: obsolete } } });
    }
    for (const [index, action] of expectedActions.entries()) {
      if (!retained[index])
        await permissions.create({ data: { action, role: publicRole.id } });
    }
  });
}

async function seedContent(strapi: Core.Strapi) {
  const seedState = strapi.store({ type: "core", name: "quote-content" });
  if (!(await seedState.get({ key: "us01-seeded" }))) {
    for (const country of planCountries) {
      const documents = strapi.documents(FORM_UID);
      const draft = await documents.findFirst({
        status: "draft",
        filters: { country },
      });
      if (!draft)
        await documents.create({
          data: seedForm(country),
          status: "published",
        });
    }
    await seedState.set({ key: "us01-seeded", value: true });
  }

  await strapi.db.transaction(async () => {
    if (await seedState.get({ key: "us02-seeded" })) return;
    const expansion: Partial<Record<(typeof planCountries)[number], string>> =
      {};
    for (const country of planCountries) {
      for (const fixture of seedPlans(country)) {
        const plan = await strapi
          .documents(PLAN_UID)
          .create({ data: fixture, status: "published" });
        if (fixture.name === "Integral") expansion[country] = plan.documentId;
      }
    }
    await seedState.set({ key: PLAN_EXPANSION_KEY, value: expansion });
    await seedState.set({ key: "us02-seeded", value: true });
  });
}

export default {
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    if (strapi.config.get("quoteCatalogMaintenance")) return;
    await restrictPublicRole(strapi);
    await seedContent(strapi);
  },
};
